// src/app/flaeche-verpachten/page.js – Landingpage für Flächeneigentümer

import { CalendarClock, HandCoins, Landmark, Wallet } from "lucide-react";

import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Querverweise from "@/components/Reusable/Querverweise";
import { Faktenleiste } from "@/components/Flaeche/Seite/teile";
import Hero from "@/components/Flaeche/Verpachten/Hero";
import Pachtmodelle from "@/components/Flaeche/Verpachten/Pachtmodelle";
import { Steuern, Vertrag } from "@/components/Flaeche/Verpachten/Vertrag";
import { Anfrage, Pruefung, Weg } from "@/components/Flaeche/Verpachten/Ablauf";
import { abs } from "@/data/site";
import { PACHT, PROVISION } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/flaeche-verpachten";
const TITEL = "Fläche für Solarpark verpachten | ÖkoInvest";
const BESCHREIBUNG =
  "Acker oder Grünland für einen Solarpark verpachten: Pachtmodelle, Vertrag, Rückbausicherheit, Steuern und Ablauf bis zur ersten Pacht. Jetzt Fläche melden.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: abs(PFAD) },
  openGraph: {
    type: "website",
    locale: "de_DE",
    url: abs(PFAD),
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/freiflaeche-begehung.jpg"), width: 1280, height: 852, alt: "Begehung einer Fläche für einen Solarpark" }],
  },
};

const FAKTEN = [
  { icon: Wallet, wert: `${fmt(PACHT.freiflaecheProHa.min)}–${fmt(PACHT.freiflaecheProHa.max)}`, einheit: "€ je Hektar und Jahr", text: `übliche Solarpacht im DACH-Raum, typisch um ${fmt(PACHT.freiflaecheProHa.mittel)} €` },
  { icon: CalendarClock, wert: `${PACHT.laufzeit} J.`, einheit: "Laufzeit", text: `ab Inbetriebnahme, dazu ${PACHT.verlaengerung}` },
  { icon: HandCoins, wert: `${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} €`, einheit: "Reservierungsprämie", text: "je Hektar und Jahr bis Baubeginn – Sie bewirtschaften weiter" },
  { icon: Landmark, wert: "0 €", einheit: "Kosten für Sie", text: `Prüfung, Angebot, Vertrag und Notar – ${PROVISION.flaeche.text}` },
];

const FAQ = [
  {
    q: "Wie viel Pacht bekomme ich für einen Solarpark?",
    a: `Für Freiflächen-PV liegen die Pachten im DACH-Raum derzeit meist zwischen ${fmt(PACHT.freiflaecheProHa.min)} und ${fmt(PACHT.freiflaecheProHa.max)} € je Hektar und Jahr, typisch um ${fmt(PACHT.freiflaecheProHa.mittel)} €. Entscheidend sind Netzanschluss, Größe, Einstrahlung und ob die Fläche in der EEG-Kulisse liegt. Das ist ein Vielfaches der üblichen Ackerpacht von durchschnittlich rund ${fmt(PACHT.ackerProHa)} € je Hektar.`,
  },
  {
    q: "Kostet mich die Prüfung oder der Vertrag etwas?",
    a: `Nein. ${PROVISION.flaeche.text[0].toUpperCase()}${PROVISION.flaeche.text.slice(1)} – Flächencheck, Pachtangebot, Vertragsentwurf und Notartermin für die Dienstbarkeit tragen wir. Eine anwaltliche oder steuerliche Prüfung auf Ihrer Seite empfehlen wir ausdrücklich; auf Wunsch beteiligen wir uns an den Kosten.`,
  },
  {
    q: "Ab wann wird die Pacht gezahlt?",
    a: `Die volle Pacht beginnt in der Regel mit Baubeginn oder Inbetriebnahme. Bis dahin – meist 2 bis 4 Jahre – zahlen wir eine Reservierungsprämie von typischerweise ${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} € je Hektar und Jahr, und Sie bewirtschaften die Fläche weiter wie bisher.`,
  },
  {
    q: "Was passiert, wenn der Solarpark doch nicht gebaut wird?",
    a: "Dann endet der Vertrag nach Ablauf einer vereinbarten Frist automatisch oder durch Rücktritt, die Dienstbarkeit wird gelöscht und Sie haben Ihre Fläche uneingeschränkt zurück. Bereits gezahlte Reservierungsprämien behalten Sie.",
  },
  {
    q: "Kann ich die Fläche während der Laufzeit verkaufen oder vererben?",
    a: "Ja. Der Pachtvertrag und die Dienstbarkeit im Grundbuch gehen auf Käufer oder Erben über – die Pacht auch. Für die Erbschaftsteuer kann die Verpachtung an einen Solarpark allerdings nachteilig sein; lassen Sie das vor der Unterschrift steuerlich prüfen.",
  },
  {
    q: "Was ist, wenn ich die Fläche bereits an einen Landwirt verpachtet habe?",
    a: "Das ist häufig. Landpachtverträge lassen sich meist mit Frist kündigen oder für Teilflächen anpassen. Wir planen die Kündigungsfristen in den Zeitplan ein und sprechen auf Wunsch mit Ihrem Pächter – oft kann er die Pflege der Fläche, etwa durch Beweidung, übernehmen.",
  },
  {
    q: "Wie sicher ist der Rückbau nach 30 Jahren?",
    a: "Die Rückbaupflicht steht im Vertrag und in der Dienstbarkeit. Zusätzlich hinterlegt der Betreiber vor Baubeginn eine Rückbaubürgschaft einer Bank oder Versicherung. Fällt der Betreiber aus, kann aus der Bürgschaft zurückgebaut werden.",
  },
];

export default function FlaecheVerpachtenPage() {
  return (
    <div>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "Service",
            name: "Pacht von Flächen für Solarparks",
            serviceType: "Flächenpacht für Freiflächen-Photovoltaik",
            provider: { "@id": `${abs("/")}/#organization` },
            areaServed: ["DE", "AT", "CH"],
            audience: { "@type": "Audience", audienceType: "Flächeneigentümer und Landwirte" },
            url: abs(PFAD),
            description: BESCHREIBUNG,
          }),
        }}
      />

      <Hero />
      <Faktenleiste titel="Eckdaten der Solarpacht" fakten={FAKTEN} />
      <Pachtmodelle />
      <Vertrag />
      <Steuern />
      <Pruefung />
      <Weg />
      <Anfrage />

      <Section tone="white" space="lg">
        <div className="grid gap-12 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
          <SectionHeading eyebrow="Häufige Fragen" title="Fragen von Flächeneigentümern" lead="Ihre Frage ist nicht dabei? Stellen Sie sie im Formular – wir antworten persönlich." />
          <Faq items={FAQ} />
        </div>
      </Section>

      <Querverweise
        items={[
          { href: "/rechner/pacht", titel: "Pachtrechner", text: "Fest, indexiert oder Umsatzbeteiligung – Ihre Pacht über 30 Jahre im Vergleich zum Ackerbau." },
          { href: "/flaechencheck", titel: "Flächencheck", text: "Ampel, Leistung und Pachtspanne Ihrer Fläche in zwei Minuten." },
          { href: "/dachflaeche-verpachten", titel: "Dachfläche verpachten", text: "Gewerbe-, Hallen- und Stalldächer ab etwa 1.000 m² – Pacht, Dachstrom oder Sanierung als Gegenleistung." },
          { href: "/landwirte", titel: "Für Landwirte", text: "Verpachten, selbst investieren oder beteiligen – die vier Wege mit Agri-PV." },
          { href: "/ratgeber/solarpark-pacht-pro-hektar", titel: "Solarpark-Pacht pro Hektar", text: "Spannen, Einflussfaktoren und ein Rechenbeispiel für 2026." },
          { href: "/ratgeber/pachtvertrag-solarpark", titel: "Pachtvertrag Solarpark", text: "Die wichtigsten Klauseln und eine Checkliste für Eigentümer." },
        ]}
      />

      <CtaBand
        eyebrow="Für Flächeneigentümer kostenfrei"
        title="Was ist Ihre Fläche als Solarpark wert?"
        text="Zwei Minuten im Flächencheck – mit Ampel, möglicher Leistung und Pachtspanne. Das Ergebnis landet auf Wunsch direkt bei unserem Flächenteam."
        primary={{ label: "Zum Flächencheck", href: "/flaechencheck" }}
        secondary={{ label: "Pachtrechner", href: "/rechner/pacht" }}
      />
    </div>
  );
}
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Querverweise from "@/components/Reusable/Querverweise";
import Hero from "@/components/Kommune/Seite/Hero";
import Fakten from "@/components/Kommune/Seite/Fakten";
import Wertschoepfung from "@/components/Kommune/Seite/Wertschoepfung";
import Verfahren from "@/components/Kommune/Seite/Verfahren";
import Kriterien from "@/components/Kommune/Seite/Kriterien";
import Partner from "@/components/Kommune/Seite/Partner";
import Anfrage from "@/components/Kommune/Seite/Anfrage";
import { BEISPIEL as beispiel, tsd } from "@/components/Kommune/Seite/daten";
import { abs, SITE } from "@/data/site";
import { KOMMUNE } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/kommunen";
const TITEL = "Solarpark für Gemeinden: Planung & Beteiligung | ÖkoInvest";
const BESCHREIBUNG =
  "Was Solarparks Gemeinden bringen: Gewerbesteuer zu 90 % am Standort, § 6 EEG mit 0,2 ct/kWh, Pacht, Bürgerbeteiligung – dazu Bauleitplanung und Kriterien.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  keywords: ["Solarpark Gemeinde", "Kommunalbeteiligung § 6 EEG", "Gewerbesteuer Solarpark", "Bauleitplanung Freiflächen-PV", "Kriterienkatalog Freiflächen-Photovoltaik", "Stadtwerke Solarpark", "Bürgerbeteiligung Solarpark"],
  alternates: { canonical: abs(PFAD) },
  openGraph: { type: "website", url: abs(PFAD), siteName: "ÖkoInvest", title: TITEL, description: BESCHREIBUNG, images: [{ url: abs("/img/solarpark-baeume.jpg"), width: 1280, height: 852, alt: "Solarpark mit Bäumen am Rand" }] },
};


const FAQ = [
  {
    q: "Was bringt ein Solarpark einer Gemeinde konkret?",
    a: `Drei direkte Einnahmen: die freiwillige Zahlung nach § 6 EEG von bis zu ${fmt(KOMMUNE.beteiligungCt, 1)} ct/kWh ab dem ersten Jahr, die Gewerbesteuer – bei Solaranlagen zu ${fmt(KOMMUNE.gewerbesteuerStandort * 100)} % an der Standortgemeinde – und Pacht, wenn Gemeindeflächen genutzt werden. Bei einem 20-MWp-Park kommen allein aus § 6 EEG rund ${tsd(beispiel.jahre[0].p6)} im Jahr zusammen. Dazu kommen Aufträge für regionale Betriebe und Beteiligungsmöglichkeiten für Bürger.`,
  },
  {
    q: "Wie läuft das Bauleitplanverfahren?",
    a: "In der Regel stellt die Gemeinde einen vorhabenbezogenen oder angebotsbezogenen Bebauungsplan auf und ändert parallel den Flächennutzungsplan. Nach dem Aufstellungsbeschluss folgen die frühzeitige Beteiligung von Öffentlichkeit und Behörden, der Entwurf mit Umweltbericht, die öffentliche Auslegung, die Abwägung und der Satzungsbeschluss. Die Planungskosten trägt üblicherweise der Projektentwickler über einen städtebaulichen Vertrag. Realistisch sind ein bis zwei Jahre.",
  },
  {
    q: "Braucht jeder Solarpark einen Bebauungsplan?",
    a: "Nicht jeder. Nach § 35 Abs. 1 Nr. 8 b BauGB sind Freiflächenanlagen in einem 200-Meter-Streifen entlang von Autobahnen und Schienenwegen des übergeordneten Netzes mit mindestens zwei Hauptgleisen privilegiert. Kleine Agri-PV-Anlagen bis 2,5 ha Grundfläche mit räumlich-funktionalem Bezug zu einem landwirtschaftlichen Betrieb sind ebenfalls privilegiert. Auch dann bleibt die Gemeinde über ihr Einvernehmen beteiligt – und viele Betreiber bieten die § 6-Zahlung trotzdem an.",
  },
  {
    q: "Wozu ein Kriterienkatalog?",
    a: "Ein vom Gemeinderat beschlossener Kriterienkatalog macht transparent, welche Flächen für Solarparks in Frage kommen und welche Anforderungen gelten – etwa zu Bodengüte, Abstand zur Wohnbebauung, Landschaftsbild, Naturschutz, Größe, Bürgerbeteiligung und Rückbausicherheit. Das spart Zeit im Verfahren und schafft Akzeptanz, weil alle Projektträger nach denselben Regeln bewertet werden.",
  },
  {
    q: "Wie können sich Bürger beteiligen?",
    a: "Über eine Genossenschaft mit kleinen Anteilen, über Nachrangdarlehen oder über vergünstigte Stromtarife. Mit Energy Sharing nach § 42c EnWG können Bürger und Gemeinde künftig Strom aus Anlagen in der Region gemeinsam nutzen. Einige Bundesländer verlangen inzwischen ausdrücklich Beteiligungsangebote für Bürger und Gemeinden.",
  },
  {
    q: "Wie ist die Lage in Österreich und der Schweiz?",
    a: "In Österreich widmet die Gemeinde Flächen für Photovoltaik (z. B. als Grünland-Photovoltaik) im Rahmen der Raumordnung des Bundeslandes; ab bestimmten Größen ist eine UVP-Prüfung erforderlich. Eine Gewerbesteuer gibt es nicht – im Vordergrund stehen Pacht, Beteiligung und Erneuerbare-Energie-Gemeinschaften. In der Schweiz erfolgt die Bewilligung über die kommunale bzw. kantonale Nutzungsplanung; seit 2026 können lokale Elektrizitätsgemeinschaften (LEG) Strom innerhalb der Gemeinde teilen.",
  },
];

export default function KommunenSeite() {
  const schema = {
    "@context": "https://schema.org",
    "@type": "Service",
    name: "Solarparks und Beteiligungsmodelle für Kommunen und Stadtwerke",
    serviceType: "Projektentwicklung Freiflächen-PV mit kommunaler Beteiligung",
    provider: { "@id": `${SITE.url}/#organization` },
    areaServed: ["DE", "AT", "CH"],
    audience: { "@type": "Audience", audienceType: "Kommunen, Stadtwerke, Gemeinderäte" },
    url: abs(PFAD),
    description: BESCHREIBUNG,
  };

  return (
    // Spannungsbogen: Hero (navy) → Fakten → Wertschöpfung (white) → Bauleitplanung (sand) → Kriterien (white)
    // → Akzeptanz & Stadtwerke (navy, Anker Mitte) → Anfrage (sand) → FAQ (white) → Querverweise → CTA.
    <div className="[&_.ov-lead]:hyphens-manual [&_h2]:hyphens-manual! lg:[&_p]:hyphens-manual">
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }} />

      <Hero />
      <Fakten />
      <Wertschoepfung />
      <Verfahren />
      <Kriterien />
      <Partner />
      <Anfrage />

      {/* ---------------- FAQ ---------------- */}
      <Section tone="white" space="lg">
        <div className="grid gap-12 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
          <SectionHeading eyebrow="Häufige Fragen" title="Solarparks in der Gemeinde" />
          <Faq items={FAQ} />
        </div>
      </Section>

      <Querverweise
        items={[
          { href: "/rechner/kommune", titel: "Kommunal-Rechner", text: "§ 6 EEG, Gewerbesteuer und Pacht mit Ihrem Hebesatz – Jahr für Jahr." },
          { href: "/genossenschaft", titel: "Genossenschaft", text: "Bürger und Landwirte beteiligen sich am Solarpark vor Ort." },
          { href: "/solarcarport", titel: "Solarcarports", text: "Parkplätze an Rathaus, Schule und Bad – Solarpflicht und Ladepunkte." },
          { href: "/prozess", titel: "Projektablauf", text: "Von der Fläche bis zur Inbetriebnahme – alle Schritte im Überblick." },
          { href: "/ratgeber/kommunale-beteiligung-6-eeg", titel: "Kommunale Beteiligung § 6 EEG", text: "Was die Gemeinde erhält und wie der Vertrag aussieht." },
          { href: "/ratgeber/buergerenergie-solarpark-akzeptanz", titel: "Bürgerenergie und Akzeptanz", text: "Solarparks gemeinsam mit der Region planen." },
        ]}
      />

      <CtaBand
        eyebrow="Für Kommunen"
        title="Planungshoheit bei Ihnen, Arbeit bei uns."
        text="Wir entwickeln Solarparks mit der Gemeinde – mit § 6-Vertrag, Beteiligungsangebot und offenen Zahlen. Die Planungskosten trägt der Entwickler."
        primary={{ label: "Gespräch anfragen", href: "#anfrage" }}
        secondary={{ label: "Kommunal-Rechner", href: "/rechner/kommune" }}
      />
    </div>
  );
}

