            <polygon points={raute(y + 5)} fill="#03122b" fillOpacity="0.06" />
            <polygon points={raute(y)} fill={EBENEN_FARBEN[i]} stroke="#558227" strokeOpacity={i === 0 ? 0.5 : 0.25} />
          </g>
        );
      })}
      {/* Oberste Ebene: Flurkarte */}
